  # Remove symmetric vertices if requested
  if remove_symmetries:
    tessellated_vertices = remove_symmetric_vertices(tessellated_vertices, eps)

  # Reverse the order of vertices to form the final basis matrix
  basis_matrix = tessellated_vertices[::-1].reshape(3, -1).T

  return basis_matrix

def remove_symmetric_vertices(vertices, eps):
  unique = set()
  for i, v in enumerate(vertices):
    if i not in unique:
      unique.add(i)
      for u in unique:
        if compute_sq_dist(vertices[i], vertices[u]) < eps and np.linalg.norm(vertices[i]) < np.linalg.norm(vertices[u]):
          unique.remove(u)
  return np.array(list(unique))
